"""Layer-3 forecasters trained on censored logs generated by the simulator: MA, RF, XGBoost, LSTM (numpy)."""
import numpy as np
from sim import *

def features(t, hist, P):
    """Operator-observable features for every point at decision day t. Returns (X (N,F), seq (N,3,5), static (N,5), rate_hat (N,))."""
    B = P.B; N = P.N
    d = t - hist.last_day
    c = hist.c.copy(); iv = hist.iv.copy()
    for k in (1, 2):                       # back-fill missing older visits with the most recent known
        c[:, k] = np.where(np.isnan(c[:, k]), c[:, k - 1], c[:, k]); iv[:, k] = np.where(np.isnan(iv[:, k]), iv[:, k - 1], iv[:, k])
    c = np.nan_to_num(c, nan=0.6 * B / 2); iv = np.where(np.isnan(iv) | (iv <= 0), P.C, iv)
    rate = c / np.maximum(iv, 1.0)
    rbar = rate.mean(1)
    cum = np.where(hist.last_day > 0, hist.tot / np.maximum(hist.last_day, 1.0), rbar)
    ang = 2 * np.pi * t / 7.0
    X = np.column_stack([d, c / B, iv, rate, rbar, cum, hist.full, hist.veh, np.sin(ang) * np.ones(N), np.cos(ang) * np.ones(N), hist.nvis])
    # sequences oldest -> newest
    seq = np.stack([np.column_stack([c[:, k] / B, np.minimum(iv[:, k], 20) / 10, np.minimum(rate[:, k], 30) / 10,
                                     np.zeros(N), np.zeros(N)]) for k in (2, 1, 0)], axis=1)
    seq[:, 2, 3] = hist.full; seq[:, 2, 4] = hist.veh
    static = np.column_stack([np.minimum(d, 40) / 10, rbar / 10, cum / 10, np.sin(ang) * np.ones(N), np.cos(ang) * np.ones(N)])
    return X, seq, static, rbar

class RandomVisitPolicy:
    """Exploration policy used only to generate training logs: each point visited w.p. p each cycle."""
    def __init__(self, p): self.p = p; self.name = 'RandomVisit'; self.fc = None; self.rows = []
    def setup(self, inst, P, seedstream=None):
        self.inst, self.P = inst, P; self.rng = np.random.default_rng([inst.seed, 33]); self.rows = []; self.cur = None
    def plan(self, c, t, q, hist, ctx):
        P = self.P; N = P.N
        if c < 2: sel = list(range(N)); self.cur = None
        else:
            sel = list(np.where(self.rng.random(N) < self.p)[0]); self.cur = (features(t, hist, P), q.copy(), t)
        l = np.minimum(P.B, 0.6 * P.B * np.ones(N)) * 0 + np.minimum(P.B, self.inst.lam * 3 * 2)
        return sel, l, None
    def observe(self, visited, takes, vlim):
        if self.cur is None or len(visited) == 0: return
        (X, seq, st, rb), q, t = self.cur
        v = np.asarray(visited)
        self.rows.append((X[v], seq[v], st[v], np.log1p(np.asarray(takes)), q[v], np.asarray(vlim), rb[v], X[v][:, 0]))

def collect_training(seeds, P, probs=(0.3, 0.5, 0.7, 1.0)):
    out = []
    for j, s in enumerate(seeds):
        inst = Instance(s, P); pol = RandomVisitPolicy(probs[j % len(probs)]); run(inst, pol, P)
        out.extend(pol.rows)
    X = np.vstack([r[0] for r in out]); S = np.concatenate([r[1] for r in out]); ST = np.vstack([r[2] for r in out])
    y = np.concatenate([r[3] for r in out]); q = np.concatenate([r[4] for r in out]); vl = np.concatenate([r[5] for r in out])
    return dict(X=X, S=S, ST=ST, y=y, q=q, vl=vl)

class MAForecaster:
    name = 'MA'
    def fit(self, D): return self
    def predict(self, t, hist, P):
        X, seq, st, rb = features(t, hist, P)
        return np.minimum(P.B, rb * X[:, 0]), rb
    def predict_rows(self, D): return np.expm1(np.log1p(np.minimum(100, D['X'][:, 14 - 3 + 0] * 0)))  # unused

class SKForecaster:
    def __init__(self, kind, seed=0):
        self.kind = kind; self.name = kind
        if kind == 'RF':
            from sklearn.ensemble import RandomForestRegressor
            self.m = RandomForestRegressor(n_estimators=40, min_samples_leaf=8, max_depth=12, n_jobs=1, random_state=seed)
        else:
            from xgboost import XGBRegressor
            self.m = XGBRegressor(n_estimators=150, max_depth=5, learning_rate=0.08, subsample=0.8, colsample_bytree=0.9,
                                  n_jobs=1, random_state=seed, verbosity=0)
    def fit(self, D): self.m.fit(D['X'], D['y']); return self
    def _pred(self, X): return self.m.predict(X)
    def predict(self, t, hist, P):
        X, seq, st, rb = features(t, hist, P)
        return np.minimum(P.B, np.expm1(np.maximum(self._pred(X), 0))), rb
    def predict_rows(self, D, B=None):
        B = B if B is not None else float(np.max(D['q']))
        return np.minimum(B, np.expm1(np.maximum(self._pred(D['X']), 0)))

class LSTMForecaster:
    """Single-layer LSTM (numpy, manual BPTT, Adam) over the last 3 visit records + static features."""
    name = 'LSTM'
    def __init__(self, nh=16, seed=0, epochs=30, bs=256, lr=3e-3):
        self.nh, self.seed, self.epochs, self.bs, self.lr = nh, seed, epochs, bs, lr
    def _init(self, nx, ns):
        r = np.random.default_rng(self.seed); nh = self.nh
        self.W = r.normal(0, 0.3, (nx + nh, 4 * nh)); self.b = np.zeros(4 * nh); self.b[nh:2 * nh] = 1.0
        self.Wo = r.normal(0, 0.3, (nh + ns, 1)); self.bo = np.zeros(1)
        self.params = [self.W, self.b, self.Wo, self.bo]
    @staticmethod
    def _sig(x): return 1 / (1 + np.exp(-np.clip(x, -30, 30)))
    def _fwd(self, S, ST):
        n, T, nx = S.shape; nh = self.nh; h = np.zeros((n, nh)); c = np.zeros((n, nh)); cache = []
        for t in range(T):
            z = np.concatenate([S[:, t], h], 1) @ self.W + self.b
            i, f, g, o = self._sig(z[:, :nh]), self._sig(z[:, nh:2 * nh]), np.tanh(z[:, 2 * nh:3 * nh]), self._sig(z[:, 3 * nh:])
            c_new = f * c + i * g; tc = np.tanh(c_new); h_new = o * tc
            cache.append((np.concatenate([S[:, t], h], 1), i, f, g, o, c, tc)); h, c = h_new, c_new
        hs = np.concatenate([h, ST], 1); y = (hs @ self.Wo + self.bo)[:, 0]
        return y, hs, cache
    def fit(self, D):
        S, ST, y = D['S'], D['ST'], D['y']; n = len(y); nh = self.nh
        self.ym, self.ys = y.mean(), y.std() + 1e-9; yt = (y - self.ym) / self.ys
        self._init(S.shape[2], ST.shape[1]); m = [np.zeros_like(p) for p in self.params]; v = [np.zeros_like(p) for p in self.params]
        rng = np.random.default_rng(self.seed + 1); step = 0
        for ep in range(self.epochs):
            perm = rng.permutation(n)
            for s0 in range(0, n, self.bs):
                ix = perm[s0:s0 + self.bs]; Sb, STb, yb = S[ix], ST[ix], yt[ix]
                pred, hs, cache = self._fwd(Sb, STb)
                dy = 2 * (pred - yb) / len(ix)
                gWo = hs.T @ dy[:, None]; gbo = np.array([dy.sum()])
                dh = (dy[:, None] @ self.Wo.T)[:, :nh]
                gW = np.zeros_like(self.W); gb = np.zeros_like(self.b); dc = np.zeros_like(dh)
                for t in reversed(range(len(cache))):
                    xin, i, f, g, o, cprev, tc = cache[t]
                    do = dh * tc; dct = dc + dh * o * (1 - tc ** 2)
                    di = dct * g; dg = dct * i; df = dct * cprev; dc = dct * f
                    dz = np.concatenate([di * i * (1 - i), df * f * (1 - f), dg * (1 - g ** 2), do * o * (1 - o)], 1)
                    gW += xin.T @ dz; gb += dz.sum(0); dh = (dz @ self.W.T)[:, S.shape[2]:]
                grads = [gW, gb, gWo, gbo]; step += 1
                for k, (p, g_) in enumerate(zip(self.params, grads)):
                    g_ = np.clip(g_, -5, 5)
                    m[k] = 0.9 * m[k] + 0.1 * g_; v[k] = 0.999 * v[k] + 0.001 * g_ ** 2
                    p -= self.lr * (m[k] / (1 - 0.9 ** step)) / (np.sqrt(v[k] / (1 - 0.999 ** step)) + 1e-8)
        return self
    def _pred(self, S, ST): return self._fwd(S, ST)[0] * self.ys + self.ym
    def predict(self, t, hist, P):
        X, seq, st, rb = features(t, hist, P)
        return np.minimum(P.B, np.expm1(np.maximum(self._pred(seq, st), 0))), rb
    def predict_rows(self, D, B=None):
        B = B if B is not None else float(np.max(D['q']))
        return np.minimum(B, np.expm1(np.maximum(self._pred(D['S'], D['ST']), 0)))

def make_forecaster(kind, D, seed=0):
    if kind == 'MA': return MAForecaster()
    if kind in ('RF', 'XGB'): return SKForecaster(kind, seed).fit(D)
    if kind == 'LSTM': return LSTMForecaster(seed=seed).fit(D)

class FCAdapter:
    def __init__(self, f): self.f = f; self.name = f.name
    def predict(self, t, hist, P): return self.f.predict(t, hist, P)

class LoggingForecastPolicy(ForecastPolicy):
    """Closed-loop policy that also logs (features, censored target) rows for retraining (feedback layer)."""
    def setup(self, inst, P, seedstream=None):
        super().setup(inst, P); self.rows = []; self.cur = None
    def plan(self, c, t, q, hist, ctx):
        out = super().plan(c, t, q, hist, ctx)
        if c >= 2: self.cur = (features(t, hist, self.P), q.copy())
        else: self.cur = None
        return out
    def observe(self, visited, takes, vlim):
        super().observe(visited, takes, vlim)
        if self.cur is None or len(visited) == 0: return
        (X, seq, st, rb), q = self.cur; v = np.asarray(visited)
        self.rows.append((X[v], seq[v], st[v], np.log1p(np.asarray(takes)), q[v], np.asarray(vlim), rb[v], X[v][:, 0]))

def merge(D1, D2):
    return {k: np.concatenate([D1[k], D2[k]]) for k in D1}

def rows_to_D(rows):
    return dict(X=np.vstack([r[0] for r in rows]), S=np.concatenate([r[1] for r in rows]), ST=np.vstack([r[2] for r in rows]),
                y=np.concatenate([r[3] for r in rows]), q=np.concatenate([r[4] for r in rows]), vl=np.concatenate([r[5] for r in rows]))

def train_closed_loop(kind, P, rounds=2, train_seeds=range(5000, 5060), theta=0.85, a=0.3, k=0.8, seed=0, D0=None):
    """DAgger-style: round 0 on random-visit logs; each later round adds logs from the forecaster's own (buffered) policy."""
    D = D0 if D0 is not None else collect_training(train_seeds, P)
    f = make_forecaster(kind, D, seed)
    if kind == 'MA': return f, D
    for r in range(rounds):
        rows = []
        for s in list(train_seeds)[:40]:
            pol = LoggingForecastPolicy(theta, a, k, forecaster=f, sigma_mode='est'); run(Instance(s, P), pol, P); rows += pol.rows
        D = merge(D, rows_to_D(rows)); f = make_forecaster(kind, D, seed)
    return f, D
